export function cropBounds(a,b,width,height){const x=Math.max(0,Math.min(width,Math.min(a.x,b.x))),y=Math.max(0,Math.min(height,Math.min(a.y,b.y))),right=Math.max(0,Math.min(width,Math.max(a.x,b.x))),bottom=Math.max(0,Math.min(height,Math.max(a.y,b.y)));return {x:Math.round(x),y:Math.round(y),width:Math.round(right-x),height:Math.round(bottom-y)};}
export function fitImage(width,height,max=2400){const scale=Math.min(1,max/Math.max(width,height));return {width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))};}
export function startPhotoEditor(onApply){
 const $=id=>document.getElementById(id),dialog=$('photoEditorDialog'),canvas=$('photoCanvas'),overlay=$('photoOverlay'),ctx=canvas.getContext('2d');let session=null,tool='arrow',gesture=null,crop=null,busy=false;
 const message=text=>{$('photoEditorStatus').textContent=text;};
 function controls(){for(const el of dialog.querySelectorAll('button,input,select'))el.disabled=busy;$('photoUndo').disabled=busy||!session?.history.length;$('applyPhotoCrop').disabled=busy||!crop||crop.width<8||crop.height<8;$('photoAnnotationText').hidden=tool!=='text';for(const el of dialog.querySelectorAll('[data-photo-tool]'))el.setAttribute('aria-pressed',String(el.dataset.photoTool===tool));}
 function clearOverlay(){overlay.width=canvas.width;overlay.height=canvas.height;crop=null;controls();}
 function remember(){session.history.push(canvas.toDataURL('image/png'));if(session.history.length>8)session.history.shift();session.changed=true;}
 async function load(blob,rotation=0){const bitmap=await createImageBitmap(blob,{imageOrientation:'from-image'});try{const size=fitImage(bitmap.width,bitmap.height),swap=rotation%180;canvas.width=swap?size.height:size.width;canvas.height=swap?size.width:size.height;ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(bitmap,-size.width/2,-size.height/2,size.width,size.height);ctx.restore();clearOverlay();}finally{bitmap.close();}}
 function point(event){const r=overlay.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width,(event.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(event.clientY-r.top)*canvas.height/r.height))};}
 function style(context){context.strokeStyle=$('photoInk').value;context.fillStyle=$('photoInk').value;context.lineWidth=Math.max(2,canvas.width/350)*Number($('photoStroke').value);context.lineCap='round';context.lineJoin='round';}
 function shape(context,a,b){style(context);if(tool==='box'){const r=cropBounds(a,b,canvas.width,canvas.height);context.strokeRect(r.x,r.y,r.width,r.height);}else if(tool==='arrow'){const angle=Math.atan2(b.y-a.y,b.x-a.x),size=context.lineWidth*4;context.beginPath();context.moveTo(a.x,a.y);context.lineTo(b.x,b.y);context.stroke();context.beginPath();context.moveTo(b.x,b.y);context.lineTo(b.x-size*Math.cos(angle-Math.PI/6),b.y-size*Math.sin(angle-Math.PI/6));context.lineTo(b.x-size*Math.cos(angle+Math.PI/6),b.y-size*Math.sin(angle+Math.PI/6));context.closePath();context.fill();}}
 function choose(next){tool=next;clearOverlay();message(next==='crop'?'Drag across the area to keep, then choose Apply crop.':next==='text'?'Enter text, then click where it should appear.':next==='pen'?'Draw on the photograph.':'Drag on the photograph to add an '+(next==='box'?'outline box.':'arrow.'));}
 overlay.onpointerdown=event=>{if(!session||busy)return;event.preventDefault();overlay.setPointerCapture(event.pointerId);const a=point(event);if(tool==='text'){const text=$('photoAnnotationText').value.trim();if(!text){message('Enter annotation text first.');$('photoAnnotationText').focus();return;}remember();style(ctx);ctx.font='bold '+Math.max(20,Math.round(canvas.width/35))+'px Arial';ctx.textBaseline='top';ctx.strokeStyle='white';ctx.lineWidth=Math.max(2,canvas.width/450);ctx.strokeText(text,a.x,a.y,canvas.width-a.x);ctx.fillText(text,a.x,a.y,canvas.width-a.x);controls();return;}gesture={a,last:a};if(tool==='pen'){remember();style(ctx);ctx.beginPath();ctx.arc(a.x,a.y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}};
 overlay.onpointermove=event=>{if(!gesture||busy)return;const b=point(event);if(tool==='pen'){style(ctx);ctx.beginPath();ctx.moveTo(gesture.last.x,gesture.last.y);ctx.lineTo(b.x,b.y);ctx.stroke();gesture.last=b;return;}const o=overlay.getContext('2d');o.clearRect(0,0,overlay.width,overlay.height);if(tool==='crop'){const r=cropBounds(gesture.a,b,canvas.width,canvas.height);o.fillStyle='#003d7c55';o.fillRect(0,0,overlay.width,overlay.height);o.clearRect(r.x,r.y,r.width,r.height);o.strokeStyle='white';o.lineWidth=Math.max(2,canvas.width/500);o.setLineDash([8,5]);o.strokeRect(r.x,r.y,r.width,r.height);}else shape(o,gesture.a,b);};
 overlay.onpointerup=event=>{if(!gesture||busy)return;const b=point(event),a=gesture.a;gesture=null;if(tool==='crop'){crop=cropBounds(a,b,canvas.width,canvas.height);message('Selected '+crop.width+' × '+crop.height+' pixels. Choose Apply crop to keep this area.');controls();}else if(tool!=='pen'&&Math.hypot(a.x-b.x,a.y-b.y)>3){remember();shape(ctx,a,b);clearOverlay();}else controls();};
 overlay.onpointercancel=()=>{gesture=null;clearOverlay();};
 for(const button of dialog.querySelectorAll('[data-photo-tool]'))button.onclick=()=>choose(button.dataset.photoTool);
 $('applyPhotoCrop').onclick=()=>{if(!crop||busy)return;const r=crop,copy=document.createElement('canvas');copy.width=r.width;copy.height=r.height;copy.getContext('2d').drawImage(canvas,r.x,r.y,r.width,r.height,0,0,r.width,r.height);remember();canvas.width=r.width;canvas.height=r.height;ctx.drawImage(copy,0,0);clearOverlay();message('Crop applied. Undo restores the previous view.');};
 $('photoRotate').onclick=()=>{if(busy)return;const copy=document.createElement('canvas');copy.width=canvas.width;copy.height=canvas.height;copy.getContext('2d').drawImage(canvas,0,0);remember();canvas.width=copy.height;canvas.height=copy.width;ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(Math.PI/2);ctx.drawImage(copy,-copy.width/2,-copy.height/2);ctx.restore();clearOverlay();message('Rotated 90° clockwise.');};
 $('photoUndo').onclick=async()=>{if(busy||!session.history.length)return;busy=true;controls();try{const data=session.history.pop(),image=new Image();image.src=data;await image.decode();canvas.width=image.width;canvas.height=image.height;ctx.drawImage(image,0,0);session.changed=true;clearOverlay();message('Last edit undone.');}catch{message('Could not undo the last edit.');}finally{busy=false;controls();}};
 $('photoReset').onclick=async()=>{if(busy)return;busy=true;controls();try{remember();await load(session.photo.variants[session.base].blob,session.baseRotation);message('Reset to the imported photo. Save photo to apply, or Undo to restore edits.');}catch{message('Could not restore the imported photo.');}finally{busy=false;controls();}};
 function cancel(){if(busy)return;session=null;gesture=null;dialog.close();canvas.width=overlay.width=1;canvas.height=overlay.height=1;}
 $('cancelPhotoEdit').onclick=cancel;dialog.addEventListener('cancel',event=>{event.preventDefault();cancel();});
 $('savePhotoEdit').onclick=async()=>{if(busy||!session)return;if(crop){message('Apply the selected crop or choose another tool before saving.');return;}if(!session.changed){cancel();return;}busy=true;controls();try{const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.95));if(!blob)throw Error('Could not create the edited photo.');if(blob.size>20*1024**2)throw Error('Edited photo is too large. Crop it before saving.');onApply(session.photo,blob,session.base,session.baseRotation);session=null;dialog.close();message('');}catch(error){message(error.message);}finally{busy=false;controls();}};
 return {async open(photo){if(session)return;const base=photo.editBaseVariant||photo.variant,baseRotation=photo.editBaseRotation??photo.rotation??0;session={photo,base,baseRotation,history:[],changed:false};busy=true;dialog.showModal();controls();message('Loading photograph…');try{await load(photo.variants[photo.variant].blob,photo.rotation||0);choose('arrow');}catch(error){message('Could not open photograph: '+error.message);session=null;dialog.close();}finally{busy=false;controls();}}};
}
